    "kernel_code": "1: \"\"\"Standalone split-K matrix multiplication with a bias epilogue.\n2: \n3: Inspired by Triton's split-K scratch / final-reduction design.\n4: Copyright 2018-2020 Philippe Tillet; Copyright 2020-2022 OpenAI.\n5: MIT license; see LICENSE. This is a bounded T4 adaptation, not upstream code.\n6: \"\"\"\n7: import torch\n8: import triton\n9: import triton.language as tl\n10: \n11: \n12: @triton.jit\n13: def _partials(A, B, WORK, M: tl.constexpr, N: tl.constexpr, K: tl.constexpr,\n14:               TILES: tl.constexpr, BM: tl.constexpr, BN: tl.constexpr,\n15:               BK: tl.constexpr):\n16:     row = tl.program_id(0) * BM + tl.arange(0, BM)\n17:     col = tl.program_id(1) * BN + tl.arange(0, BN)\n18:     split = tl.program_id(2)\n19:     lane = tl.arange(0, BK)\n20:     accum = tl.zeros((BM, BN), tl.float32)\n21:     for tile in range(TILES):\n22:         inner = (split * TILES + tile) * BK + lane\n23:         left = tl.load(A + row[:, None] * K + inner[None, :],\n24:                        mask=(row[:, None] < M) & (inner[None, :] < K), other=0.)\n25:         right = tl.load(B + inner[:, None] * N + col[None, :],\n26:                         mask=(inner[:, None] < K) & (col[None, :] < N), other=0.)\n27:         accum = tl.dot(left, right, accum)\n28:     offset = split * M * N + row[:, None] * N + col[None, :]\n29:     tl.store(WORK + offset, accum, mask=(row[:, None] < M) & (col[None, :] < N))\n30: \n31: \n32: @triton.jit\n33: def _finish(WORK, BIAS, OUT, M: tl.constexpr, N: tl.constexpr,\n34:             SPLITS: tl.constexpr, BLOCK: tl.constexpr):\n35:     index = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n36:     value = tl.zeros((BLOCK,), tl.float32)\n37:     for split in range(SPLITS):\n38:         partial = tl.load(WORK + split * M * N + index, mask=index < M * N, other=0.)\n39:         value += partial.to(tl.float32)\n40:     bias = tl.load(BIAS + index % N, mask=index < M * N, other=0.)\n41:     tl.store(OUT + index, value + bias, mask=index < M * N)\n42: \n43: \n44: def validate_inputs(a, b, bias, split_k, require_cuda=True):\n45:     \"\"\"Check the complete public domain; reference checks can also run on CPU.\"\"\"\n46:     def require(condition, message):\n47:         if not condition:\n48:             raise ValueError(message)\n49:     values = (a, b, bias)\n50:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n51:     for tensor in values:\n52:         require(type(tensor) is torch.Tensor, \"standard torch.Tensor required\")\n53:         require(tensor.layout == torch.strided and tensor.is_contiguous(), \"contiguous strided tensor required\")\n54:         require(not tensor.requires_grad and not tensor.is_inference(), \"ordinary non-gradient tensors required\")\n55:         require(not tensor.is_neg() and not tensor.is_conj(), \"materialized logical values required\")\n56:     require(all(t.device == a.device for t in values), \"all tensors must share a device\")\n57:     require(not require_cuda or a.is_cuda, \"run requires CUDA\")\n58:     require(a.ndim == b.ndim == 2 and bias.ndim == 1, \"expected two matrices and a bias vector\")\n59:     m, k = a.shape\n60:     kb, n = b.shape\n61:     require(k == kb and bias.shape == (n,), \"matrix and bias dimensions disagree\")\n62:     require(1 <= m <= 64 and 1 <= n <= 64 and 1 <= k <= 512, \"shape outside supported domain\")\n63:     require(a.dtype == b.dtype == torch.float16 and bias.dtype == torch.float32, \"A/B must be FP16 and bias FP32\")\n64:     require(type(split_k) is int and split_k in (1, 2, 4, 8), \"split_k must be 1, 2, 4 or 8\")\n65:     for tensor, bound in ((a, .5), (b, .5), (bias, 1.)):\n66:         require(bool(torch.isfinite(tensor).all().item()), \"finite values required\")\n67:         require(bool((tensor.abs() <= bound).all().item()), \"input magnitude outside domain\")\n68:     intervals = [(t.data_ptr(), t.data_ptr() + t.numel() * t.element_size()) for t in values]\n69:     require(all(a1 <= b0 or b1 <= a0 for i, (a0, a1) in enumerate(intervals)\n70:                 for b0, b1 in intervals[i + 1:]), \"input storage ranges must be disjoint\")\n71:     return {\"valid\": True, \"m\": m, \"n\": n, \"k\": k, \"split_k\": split_k}\n72: \n73: \n74: def run(a, b, bias, split_k=4):\n75:     \"\"\"Return a fresh FP32 CUDA result; input buffers are preserved.\"\"\"\n76:     validate_inputs(a, b, bias, split_k)\n77:     m, k = a.shape\n78:     n = b.shape[1]\n79:     tiles = triton.cdiv(triton.cdiv(k, 32), split_k)\n80:     work_dtype = torch.float32\n81:     work = torch.empty((split_k, m, n), dtype=work_dtype, device=a.device)\n82:     out = torch.empty((m, n), dtype=torch.float32, device=a.device)\n83:     with torch.cuda.device(a.device):\n84:         _partials[(triton.cdiv(m, 16), triton.cdiv(n, 16), split_k)](\n85:             a, b, work, M=m, N=n, K=k, TILES=tiles, BM=16, BN=16, BK=32,\n86:             num_warps=4, num_stages=2)\n87:         _finish[(triton.cdiv(m * n, 256),)](\n88:             work, bias, out, M=m, N=n, SPLITS=split_k, BLOCK=256, num_warps=4)\n89:     return out\n90: \n91: \n92: def reference(a, b, bias, split_k=4):\n93:     \"\"\"FP64 full matrix product; independent of split count and scratch layout.\"\"\"\n94:     validate_inputs(a, b, bias, split_k, require_cuda=False)\n95:     return torch.matmul(a.double(), b.double()) + bias.double()[None, :]\n96: \n97: \n98: def make_inputs(device=\"cuda\", m=17, n=33, k=257, split_k=4, seed=0):\n99:     \"\"\"A convenience example, not a restriction on the legal input values.\"\"\"\n100:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n101:     a = (torch.rand((m, k), generator=generator) - .5).half()\n102:     b = (torch.rand((k, n), generator=generator) - .5).half()\n103:     bias = (2 * torch.rand((n,), generator=generator) - 1).float()\n104:     return a.to(device), b.to(device), bias.to(device), split_k",
